  &lt;img alt="2025.06.24 17:43 by john kafka" src="https://game.donga.com/media/__sized__/images/2026/9/7/9a5026442e80442e-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
   2025.06.24 17:43 by john kafka
  &lt;/figcaption&gt;
 &lt;/figure&gt;
